            node = trie
            for char in prefix:
                if char not in node:
                    return []
                node = node[char]
            temp = []
            collect(node, temp)
            return temp

        for end in range(1, len(searchWord) + 1):
            res.append(dfs(searchWord[:end]))
        return res

