    def removeKdigits(self, num: str, k: int) -> str:

        if len(num) == k:
            return "0"

        stack = []

        for i in range(len(num)):

            cur = int(num[i])

            while stack and int(num[stack[-1]]) > cur and k:
                stack.pop()
                k-=1

            stack.append(i)

        res = ""

